function useRecording(append=false){narrative.value=append && narrative.value.trim()?`${narrative.value}\n\n${recordingText.value}`:recordingText.value;markDirty();}
function toggleIntervention(value){const list=smart.value.interventionsSelected;smart.value.interventionsSelected=list.includes(value)?list.filter(item=>item!==value):[...list,value];}
function focusFinding({checkId,finding}){if(finding?.action==='clinical_service'){nextTick(()=>{const field=document.getElementById('mobile-underlying-service');field?.scrollIntoView?.({block:'center',behavior:'smooth'});field?.focus();});return;}if(finding?.action==='assessment'){showAssessmentEvidence.value=true;nextTick(()=>document.getElementById('mobile-assessment-evidence')?.scrollIntoView?.({block:'start',behavior:'smooth'}));return;}document.getElementById(checkId==='risk_safety'?'mobile-risk-assessment':checkId==='service_code'?'mobile-encounter-details':'mobile-session-narrative')?.scrollIntoView?.({block:'start',behavior:'smooth'});}
watch(()=>[mode.value,generationInput(),encounter.serviceCode,output.value.meta?.generationReceipt],refreshGeneration,{deep:true});
watch(()=>review.value?.riskAssessmentRequired,value=>{if(value)riskRequiredLatched.value=true;});
watch([narrative,output,smart,encounter,ratings,riskIncluded,riskCompleted,riskText,riskChoices,mode,assessmentEvidence,underlyingServiceCode],markDirty,{deep:true});
watch(()=>JSON.stringify(selection.value),async()=>{if(dirty.value && !await save())return;await load();},{immediate:true});
onBeforeRouteUpdate(async(to,from)=>{if(to.fullPath!==from.fullPath && dirty.value)return await save();});
onBeforeRouteLeave(async()=>!dirty.value || await save());
onMounted(()=>{document.addEventListener('visibilitychange',beforeHidden);window.addEventListener('pagehide',pageHidden);window.addEventListener('beforeunload',beforeUnload);});
onBeforeUnmount(()=>{stashRecovery();disposed=true;generation++;clearTimeout(saveTimer);invalidate();document.removeEventListener('visibilitychange',beforeHidden);window.removeEventListener('pagehide',pageHidden);window.removeEventListener('beforeunload',beforeUnload);});
</script>

<template>
  <section class="mobile-note-workspace"><button type="button" class="mn-back" @click="back">← Back</button><header><div><p>Note Workspace</p><h1>{{ readOnly ? 'Finalized note' : 'Document this session' }}</h1></div><img :src="NARRIVA_BRAND.logo" alt="Narriva by AuricWell" /></header><p v-if="loading" role="status">Loading your session and note…</p><p v-if="error" class="mn-error" role="alert">{{ error }}</p><p v-if="recoveryWarning" class="mn-alert" role="alert">{{ recoveryWarning }}</p><p v-if="notice" class="mn-notice" role="status">{{ saving?'Saving…':notice }}</p>
    <template v-if="context && !loading"><button type="button" class="mn-client" @click="openProfile"><strong>{{ context.client?.maskedName || 'Client' }}</strong><span>{{ context.client?.age != null ? `Age ${context.client.age}` : 'Age unavailable' }}</span><span>Contact &amp; profile ›</span></button><p v-for="(alert,index) in context.alerts" :key="alert.id || index" class="mn-alert">{{ alert.message || alert }}</p>
      <section v-if="recoveryCopy && !readOnly" class="mn-card mn-recovery" role="status"><h2>Unsaved text is available</h2><p>Text from this same account and encounter was kept in this app’s memory when it locked. Nothing has replaced the current server draft.</p><p v-if="recoveryCopy.serverChanged">The server draft has also changed. Review the recovered copy before saving.</p><button type="button" @click="restoreRecovery">Restore unsaved draft</button><button type="button" @click="discardRecovery">Discard recovery copy</button></section>
      <NarrivaModeChooser compact v-if="!readOnly" v-model="mode" :default-mode="defaultMode" :allow-manual="context.preferences?.features?.manualAllowed !== false" :allow-narriva="context.preferences?.features?.writing !== false" :allow-smart="context.preferences?.features?.writing !== false" :saving="preferenceSaving" :error="preferenceError" @save-default="setDefault" />
      <details id="mobile-encounter-details" class="mn-card" open><summary>Encounter details</summary><div class="mn-fields"><label>Date of service<input v-model="encounter.dateOfService" type="date" :disabled="readOnly" /></label><div class="mn-service-field"><label>Service<select v-model="encounter.serviceCode" :disabled="readOnly"><option value="">Select service</option><option v-for="item in context.serviceCodes" :key="item.code || item.serviceCode" :value="item.code || item.serviceCode">{{ item.code || item.serviceCode }} · {{ item.label || item.name }}</option></select></label><ServiceInformation presentation="button" :service-code="encounter.serviceCode" :agency-id="context.agencyId" :service-info="service?.serviceInfo || null" :api-client="api" reference-base-path="/service-reference" /></div><label>Start<input v-model="encounter.startTimeLocal" type="time" :disabled="readOnly" /></label><label>End<input v-model="encounter.endTimeLocal" type="time" :disabled="readOnly" /></label><label>Duration (minutes)<input v-model="encounter.durationMinutes" type="number" min="1" :disabled="readOnly" /></label><label class="mn-wide">Participants<select v-model="encounter.participants" :disabled="readOnly"><option value="">Choose participants</option><option v-if="encounter.participants && !['Client Only','Client and Parent/Guardian','Parent/Guardian without Client','Client and Other Participants'].includes(encounter.participants)" :value="encounter.participants">{{ encounter.participants }}</option><option>Client Only</option><option>Client and Parent/Guardian</option><option>Parent/Guardian without Client</option><option>Client and Other Participants</option></select></label><ClinicalLocationPicker class="mn-wide" :model-value="encounter" :choices="locationChoices" :disabled="readOnly" :unavailable="context.locationChoicesUnavailable" @update:model-value="Object.assign(encounter,$event)" /></div><label class="mn-check"><input v-model="encounter.consentConfirmed" type="checkbox" :disabled="readOnly" />I confirm consent to participate was obtained for this encounter.</label></details>
      <section v-if="isProBonoFundingCode(encounter.serviceCode)" class="mn-card"><div class="mn-service-field"><label>Clinical service provided<select id="mobile-underlying-service" v-model="underlyingServiceCode" :disabled="readOnly"><option value="">Choose clinical service</option><option v-if="underlyingServiceCode && !underlyingOptions.some(item => item.code === underlyingServiceCode)" :value="underlyingServiceCode" disabled>{{ underlyingServiceCode }} · Eligibility needs review</option><option v-for="item in underlyingOptions" :key="item.code" :value="item.code">{{ item.code }} · {{ item.label || item.name || item.code }}</option></select></label><ServiceInformation presentation="button" :service-code="underlyingServiceCode" :agency-id="context.agencyId" :service-info="underlyingOptions.find(item => item.code === underlyingServiceCode)?.serviceInfo || null" :api-client="api" reference-base-path="/service-reference" /></div><p>Pro Bono remains the funding arrangement. This choice identifies the clinical service for documentation review and does not change its scheduled or charged code.</p><p v-if="!underlyingServiceCode">Choose the clinical service to verify its handbook requirements. Until then, this note remains unverified.</p></section>
      <p v-if="serviceVerificationError" class="mn-alert" role="alert">{{ serviceVerificationError }} <button type="button" @click="refreshServiceStatus">Retry service verification</button></p>
      <section v-if="serviceChanged && !readOnly" class="mn-card mn-service-confirm"><h2>{{ pendingConfirmation ? 'Finish pending service change' : 'Confirm service-code change' }}</h2><p v-if="pendingConfirmation">The prior confirmation is pending. Review the preserved service and reason, then explicitly retry it.</p><p v-if="servicePendingOther">Another authorized service change is pending. Its author must finish it before this note can proceed.</p><p>The scheduled encounter still uses {{ context.session?.serviceCode || 'its original service' }}. Narriva will not change a billed service automatically.</p><label>Reason / crisis justification<textarea v-model="serviceReason" :readonly="!!pendingConfirmation || servicePendingOther" rows="3" minlength="5" maxlength="4000" /></label><button type="button" :disabled="serviceSaving || servicePendingOther || serviceReason.trim().length<5" @click="confirmService">{{ serviceSaving?'Checking eligibility…':pendingConfirmation?'Retry confirmation':'Confirm service change' }}</button></section>
      <details v-if="goals.length" class="mn-card" open><summary>Treatment plan &amp; current scores</summary><section v-for="goal in goals" :key="goal.id"><h3>{{ goal.title || goal.goal_text }}</h3><label v-for="objective in goal.objectives" :key="objective.id" class="mn-objective"><span>{{ objective.title || objective.objective_text }}<small>Previous {{ objective.previousScore ?? '—' }} · Target {{ objective.scaleTarget ?? '—' }}</small></span><input v-model="ratings[objective.id]" type="number" step="any" aria-label="Current objective score" :disabled="readOnly" placeholder="Now" /></label></section></details>
      <section v-if="mode === 'smart_notes' && !readOnly" class="mn-card mn-smart"><h2>Smart Notes</h2><p>Guided note builder · Powered by Narriva</p><nav aria-label="Guided note steps"><button v-for="(title,index) in ['Focus','Interventions','Response','Necessity','Plan']" :key="title" type="button" :aria-pressed="smartStep===index" @click="smartStep=index">{{ index+1 }}. {{ title }}</button></nav><label v-if="smartStep===0">Session focus<textarea v-model="smart.sessionFocus" rows="5" /></label><template v-else-if="smartStep===1"><p>Select interventions actually used.</p><div class="mn-chips"><button v-for="item in CS_DEFAULT_INTERVENTIONS.slice(0,12)" :key="item" type="button" :aria-pressed="smart.interventionsSelected.includes(item)" @click="toggleIntervention(item)">{{ item }}</button></div><label>Other interventions and how they were used<textarea v-model="smart.interventionsCustom" rows="4" /></label></template><label v-else-if="smartStep===2">Engagement and response to interventions<textarea v-model="smart.clientResponseMore" rows="5" /></label><label v-else-if="smartStep===3">Symptoms, functional impact and medical necessity<textarea v-model="smart.medicalNecessityNarrative" rows="5" /></label><label v-else>Progress and plan for next service<textarea v-model="smart.planEdited" rows="5" /></label><div class="mn-step-actions"><button v-if="smartStep>0" type="button" @click="smartStep--">Previous</button><button v-if="smartStep<4" type="button" @click="smartStep++">Next</button></div></section>
      <section v-if="mode==='narriva' && !readOnly" id="mobile-session-narrative" class="mn-card"><h2>Session Narrative</h2><p class="mn-privacy">Please do not enter or speak names, dates of birth, contact details, or other identifiers here. Use Client, Provider, parent or guardian. Record spoken content from the session page.</p><textarea v-model="narrative" aria-label="Session Narrative" rows="8" maxlength="150000" placeholder="Describe what occurred, the interventions, response, progress, and next plan…" /><button type="button" @click="openRecorder" :disabled="!context.session?.id && !context.session?.officeEventId">Open session recorder</button><template v-if="recordingText && recordingText !== narrative"><p>A reviewed recording narrative is available for this encounter.</p><button type="button" @click="useRecording(true)">Append recording narrative</button><button type="button" @click="useRecording(false)">Replace with recording narrative</button></template></section>
      <button v-if="mode!=='manual' && !readOnly" type="button" class="mn-generate" :disabled="generating || saving || blockingAlerts.length>0" @click="generate"><img :src="NARRIVA_BRAND.icon" alt="" />{{ generating?'Generating your note…':'Narriva Generate Note' }}</button>
      <p v-if="hasContent && !showOutput" class="mn-notice">Saved note content is preserved. Generate from the Session Narrative, or choose Manual Writer to edit the saved note.</p>
      <section v-if="showOutput" class="mn-card mn-note"><p v-if="mode!=='manual' && !readOnly && !generatedCurrent" class="mn-alert">The source has changed. Generate again before checking or signing this note.</p><h2>{{ readOnly?'Signed note':mode==='manual'?'Manual writer':'Generated note' }}</h2><label v-for="(_text,title) in sections" :key="title">{{ title }}<textarea v-model="output.sections[title]" :aria-label="`${title} note section`" rows="5" :disabled="readOnly || manualBlocked || mode!=='manual' && !generatedCurrent" /></label><p v-if="manualBlocked">Manual editing is disabled by your profile. Choose an available writer to continue; the existing content is preserved.</p><button v-if="!readOnly" type="button" :disabled="saving || manualBlocked || !hasContent && !narrative.trim()" @click="save(true)">{{ saving?'Saving…':'Save draft' }}</button></section>
      <NarrivaCompliancePanel v-if="(!readOnly || canCosign) && prepared && reviewStarted && (review || reviewBusy || reviewError || requiredRisk || riskIncluded)" :read-only="canCosign" :review="review" :risk-assessment-required="requiredRisk" :busy="reviewBusy" :error="reviewError" @retry="checks" @resolve="resolveFinding" @action="focusFinding"><template #risk><div class="mn-risk-choice"><strong>Include a risk assessment?</strong><span v-if="requiredRisk">Required for this note</span><template v-else-if="!readOnly"><label><input :checked="!riskIncluded" type="radio" name="mobile-risk" @change="riskIncluded=false" />No</label><label><input :checked="riskIncluded" type="radio" name="mobile-risk" @change="riskIncluded=true" />Yes</label></template></div><section v-if="requiredRisk || riskIncluded" id="mobile-risk-assessment"><label v-for="domain in riskDomains" :key="domain">{{ domain }}<select v-model="riskChoices[domain]" :disabled="readOnly"><option value="">Choose assessed finding</option><option>Denied</option><option>Present</option><option>Unable to assess</option></select></label><label>Risk assessment and safety interventions<textarea v-model="riskText" :disabled="readOnly" rows="5" placeholder="Document the assessment actually performed, findings, and any safety interventions." /></label><label class="mn-check"><input v-model="riskCompleted" :disabled="readOnly" type="checkbox" />I completed and reviewed this documented risk assessment.</label></section></template></NarrivaCompliancePanel>
      <NarrivaAssessmentEvidence v-if="!readOnly && (showAssessmentEvidence || assessmentEvidence.length)" id="mobile-assessment-evidence" v-model="assessmentEvidence" :agency-id="context.agencyId" :client-id="context.client?.id" :clinical-session-id="context.session?.id" :draft-id="draftId" :note-id="context.note?.id" :api-client="api" base-url="/assessments" />
      <button v-if="(!readOnly || canCosign) && hasContent && prepared" type="button" :disabled="reviewBusy || saving" @click="checks">{{ reviewBusy?'Checking…':mode==='manual'?'Check Note':'Run Narriva checks' }}</button>
      <section v-if="canCosign" class="mn-card mn-sign"><h2>Supervisor review</h2><label class="mn-check"><input v-model="cosignAttested" type="checkbox" :disabled="signing" />I reviewed the current note, encounter details and attached entries and approve this documentation under my supervisory responsibility.</label><button v-if="review?.status==='passed' && review?.quickSignEligible===true" type="button" class="mn-quick-sign" :disabled="signing || reviewBusy || !cosignAttested" @click="cosign(true)">✓ Quick Sign</button><button type="button" :disabled="signing || reviewBusy || !cosignAttested" @click="cosign(false)">{{ signing?'Saving signature…':'Review &amp; co-sign' }}</button></section>
      <section v-else-if="!readOnly && reviewComplete" class="mn-card mn-sign"><h2>Review &amp; sign</h2><label class="mn-check"><input v-model="accurate" type="checkbox" />I reviewed this note and confirm it is accurate and complete.</label><label class="mn-check"><input v-model="necessary" type="checkbox" />I attest that this service was medically necessary.</label><p v-if="!context.session?.id">An authorized encounter must be linked before chart signing.</p><button type="button" :disabled="signing || saving || reviewBusy || manualBlocked || serviceChanged || !!serviceVerificationError || !accurate || !necessary || !hasContent || !context.session?.id || context.note?.canSignClinicalNote === false || blockingAlerts.length>0 || requiredRisk && (!riskCompleted || !riskDomainComplete)" @click="sign">{{ signing?'Saving signature…':'Sign & save to chart' }}</button><p>The supervisor co-signature follows your workspace’s existing requirements.</p></section>
    </template>
  </section>
</template>

<style scoped>
.mn-service-field{display:flex;align-items:flex-end;gap:8px;min-width:0}.mn-service-field>label{flex:1;min-width:0}.mn-service-field>.service-information{align-self:flex-end;margin-bottom:6px}

.mobile-note-workspace{background:#f7f9fc;padding:15px;color:#173754;min-width:0}.mobile-note-workspace button{font:inherit;cursor:pointer;border:1px solid #cbd8e5;border-radius:9px;background:#f3f7fc;color:#23577f;padding:10px 12px}.mobile-note-workspace button:disabled{opacity:.5;cursor:default}.mn-back{margin-bottom:16px}.mobile-note-workspace>header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.mobile-note-workspace header p{font-size:11px;letter-spacing:.07em;text-transform:uppercase;margin:0;color:#6c8194}.mobile-note-workspace h1{font-size:21px;margin:5px 0}.mobile-note-workspace header>img{width:125px;max-width:37%;height:auto}.mn-client{display:flex;align-items:center;flex-wrap:wrap;gap:8px;width:100%;text-align:left;background:#fff!important;border-color:#d9e3ed!important;margin-bottom:15px}.mn-client strong{font-size:16px;flex:1}.mn-client span{font-size:12px;color:#6b8195}.mn-client span:last-child{font-size:10px;color:#23577f}.mn-card{background:#fff;border:1px solid #dbe4ee;border-radius:12px;padding:15px;margin:14px 0}.mn-card summary{font-weight:650;cursor:pointer;font-size:15px}.mn-card h2{font-size:17px;margin:0 0 12px}.mn-card h3{font-size:13px;margin:15px 0 8px}.mn-card p{font-size:12px;line-height:1.6;color:#6b8092}.mobile-note-workspace label{display:block;font-size:12px;color:#42617b;margin:11px 0;font-weight:550}.mobile-note-workspace input:not([type=checkbox]):not([type=radio]),.mobile-note-workspace textarea,.mobile-note-workspace select{display:block;box-sizing:border-box;width:100%;font:inherit;font-size:15px;margin-top:6px;border:1px solid #cbd9e6;padding:11px 10px;border-radius:8px;background:#fff;color:#173754;min-width:0}.mobile-note-workspace textarea{resize:vertical;line-height:1.6}.mn-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 10px;margin-top:10px}.mn-wide{grid-column:1/-1}.mobile-note-workspace .mn-check{display:flex;align-items:flex-start;gap:8px;line-height:1.6;font-weight:400}.mn-check input{margin-top:4px;flex:none}.mn-objective{display:flex!important;align-items:center;gap:10px}.mn-objective>span{flex:1;line-height:1.5}.mn-objective small{display:block;font-size:10px;color:#7a8fa1}.mn-objective input{max-width:68px}.mn-smart nav{display:flex;gap:5px;overflow:auto;margin:10px 0 17px;padding-bottom:4px}.mn-smart nav button{font-size:11px;white-space:nowrap;padding:8px}.mn-smart button[aria-pressed=true]{background:#1c5885;color:#fff;border-color:#1c5885}.mn-chips{display:flex;flex-wrap:wrap;gap:6px}.mn-chips button{font-size:11px;padding:7px 9px}.mn-step-actions{display:flex;justify-content:space-between;gap:10px}.mobile-note-workspace .mn-generate{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;background:#174f7c;color:white;border-color:#b79648;box-shadow:0 2px 5px #12345515;font-weight:650}.mn-generate img{width:26px;height:26px;object-fit:contain;background:#fff;border-radius:6px;padding:3px}.mn-privacy{padding:10px;background:#f2f6fb;border-left:3px solid #caab55}.mn-risk-choice{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:12px;font-size:12px}.mn-risk-choice label{display:flex;align-items:center;gap:4px;margin:0}.mn-risk-choice>span{color:#94621e}.mn-sign>button{width:100%;background:#1e5a82;color:#fff}.mn-sign p{font-size:11px}.mn-error,.mn-alert{color:#a32d2a;background:#fff0ed;padding:11px;border-radius:8px;font-size:13px;line-height:1.6}.mn-notice{font-size:12px;color:#28744f}.mobile-note-workspace :deep(.narriva-modes){margin-bottom:14px}.mobile-note-workspace :deep(.narriva-compliance){padding:13px;margin:14px 0}.mobile-note-workspace :deep(.narriva-compliance footer){flex-wrap:wrap}@media(max-width:350px){.mobile-note-workspace{padding:10px}.mn-card{padding:11px}.mn-fields{gap:0 7px}.mobile-note-workspace input:not([type=checkbox]):not([type=radio]),.mobile-note-workspace select{font-size:13px;padding:10px 6px}}
</style>

<style scoped>
.mobile-note-workspace{font-size:14px;line-height:1.45;max-width:100%;box-sizing:border-box}.mn-card{min-width:0;padding:14px}.mn-fields{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 12px}.mn-fields>*{min-width:0;max-width:100%}.mobile-note-workspace input:not([type=checkbox]):not([type=radio]),.mobile-note-workspace select,.mobile-note-workspace textarea{box-sizing:border-box;width:100%;min-width:0;max-width:100%;font-size:16px!important;line-height:1.35;padding:9px 10px;min-height:42px}.mobile-note-workspace input[type=date],.mobile-note-workspace input[type=time]{display:block;appearance:none;-webkit-appearance:none}.mobile-note-workspace input::-webkit-date-and-time-value{min-width:0;text-align:left}.mn-fields label{font-size:12px;margin:6px 0}.mn-service-field{min-width:0;max-width:100%}.mn-service-field>label{min-width:0;flex:1}.mn-service-field :deep(.service-info-button){flex-shrink:0}.mobile-note-workspace h1{font-size:20px}.mobile-note-workspace h2,.mobile-note-workspace summary{font-size:16px}.mobile-note-workspace p{font-size:13px}.mn-check{font-size:13px;line-height:1.5}@media(max-width:520px){.mn-fields{grid-template-columns:minmax(0,1fr)}.mn-wide{grid-column:auto}.mobile-note-workspace{padding:12px}.mn-card{padding:12px}}
</style>
